import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"中吕·迎仙客感旧","description":"","frontmatter":{"title":"中吕·迎仙客感旧","date":"2026-11-11T00:00:00.000Z","seq":7,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/中吕·迎仙客感旧.md","filePath":"blogs/元曲·张可久/中吕·迎仙客感旧.md"}'),o={name:"blogs/元曲·张可久/中吕·迎仙客感旧.md"};function c(l,a,n,_,m,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="中吕·迎仙客感旧" tabindex="-1">中吕·迎仙客感旧 <a class="header-anchor" href="#中吕·迎仙客感旧" aria-label="Permalink to &quot;中吕·迎仙客感旧&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">鹦鹉洲，凤凰楼，十年故人怀旧游。</p><p class="poem-stanza">杜陵花，陶令酒，酒病花愁，不觉的今春瘦。</p><p class="poem-stanza">湖上送别钓锦鳞，棹红云，西湖画船三月春。</p><p class="poem-stanza">正思家，还送人，绿满前村，烟雨江南恨。</p><p class="poem-stanza">春日湖上二首雨亦奇，锦成围，笙歌满城莺燕飞。</p><p class="poem-stanza">紫霞杯，金缕衣，倒著接篱，湖上山翁醉。</p><p class="poem-stanza">舞绛纱，扣红牙，耳边玉人催人马。</p><p class="poem-stanza">雪儿歌，苏小家，月淡梨花，醉倚秋千架。</p><p class="poem-stanza">春晚看牡丹，倚阑干，宿酒乍醒欹髻鬟。</p><p class="poem-stanza">燕初忙，莺正懒，帘卷轻寒，玉手调筝雁。</p><p class="poem-stanza">秋夜雨乍晴，月笼明，秋香院落砧杵鸣。</p><p class="poem-stanza">二三更，千万声，捣碎离情，不管愁人听。</p><p class="poem-stanza">黄桂近玉阶，映瑶台，婆娑小丛岩畔栽。</p><p class="poem-stanza">雁初飞，花正开，金粟如来，望月佳人拜。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
